WITH with_windows AS (SELECT id, shipped_date, delivered_date, status, AVG(cost) OVER (PARTITION BY carrier, status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_cost, MIN(cost) OVER (PARTITION BY carrier, status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_cost, SUM(cost) OVER (PARTITION BY carrier, status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_cost, MAX(cost) OVER (PARTITION BY carrier, status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_cost FROM shipments), base AS (SELECT *, LAST_DAY(delivered_date) AS delivered_date_month_end FROM with_windows WHERE running_max_cost BETWEEN 31 AND 60), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date_month_end DESC NULLS LAST, id) AS row_num FROM base) ranked WHERE row_num = 1), filtered AS (SELECT *, SUBSTRING(status, 1, 2) AS status_prefix FROM ranked WHERE row_num < 1), ranked_shipments AS (SELECT id, status, delivered_date_month_end FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY running_sum_cost DESC, id) AS dedup_rank FROM filtered) t WHERE dedup_rank = 1), metrics AS (SELECT id, status, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date_month_end, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date_month_end, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date_month_end, id) AS event_seq_2 FROM ranked_shipments), scored AS (SELECT *, MAX(event_seq_2) OVER (PARTITION BY status) AS status_max_event_seq_2, AVG(row_seq) OVER (ORDER BY event_seq, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS row_seq_avg_5 FROM metrics WHERE row_seq > 4) SELECT status, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) AS delivered_count, SIZE(COLLECT_SET(status)) AS num_status, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN status = 'IN_TRANSIT' THEN 1 END), 0), 2) AS event_seq_per_in_transit FROM scored GROUP BY status HAVING delivered_count > 1;
